import { ReactNode } from 'react';
export type LocaleModule = {
    default?: Record<string, unknown>;
} & Record<string, unknown>;
export type LocaleRequireContext = {
    keys: () => string[];
    (fileName: string): LocaleModule;
};
export type TmsIntlProviderConfig = {
    mfe: string;
    translationPrefix: string;
    defaultLocale: string;
    localLanguagesContext: LocaleRequireContext;
    builtLocalesContext?: LocaleRequireContext;
    enableBFF?: boolean;
};
export type TmsIntlProviderProps = {
    children?: ReactNode;
};
